import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {Array<number>} [position]
 * @property {Array<number>} [rotation]
 * @property {Array<number>} [scale]
 * @property {Object} [assets]
 * @property {string} [assets.imageUrl]
 * @property {Object} [atlas]
 * @property {Array<number>} [atlas.sourceRect] // [x, y, w, h]
 * @property {Array<Object>} [cinematicPrimitives]
 */

/**
 * @typedef {Object} NodeContext
 * @property {{ load: (url:string)=>THREE.Texture }} textureLoader
 * @property {THREE.Camera} [camera]
 * @property {Object.<string, Function>} primitives
 */

/**
 * Creates a billboarded textured plane.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const {
    position = [0, 0, 0],
    rotation = [0, 0, 0],
    scale = [1, 1, 1],
    assets = {},
    atlas = {},
    cinematicPrimitives = [],
  } = config;

  // Load texture synchronously via the provided loader
  const tex = ctx.textureLoader.load(assets.imageUrl);

  // Apply atlas UV offset/repeat if a source rect is defined
  if (atlas.sourceRect && tex.image) {
    const [srcX, srcY, srcW, srcH] = atlas.sourceRect;
    const img = tex.image;
    tex.offset.set(srcX / img.width, srcY / img.height);
    tex.repeat.set(srcW / img.width, srcH / img.height);
  }

  // Determine plane aspect ratio from atlas rect (fallback to 1:1)
  const aspect = atlas.sourceRect
    ? atlas.sourceRect[2] / atlas.sourceRect[3]
    : 1;

  const geometry = new THREE.PlaneGeometry(aspect, 1);
  const material = new MeshBasicNodeMaterial({
    map: texture(tex),
    transparent: true,
    depthTest: true,
  });

  const mesh = new THREE.Mesh(geometry, material);

  // Apply transforms from config
  mesh.position.set(...position);
  mesh.rotation.set(...rotation);
  mesh.scale.set(...scale);

  // Simple billboard: face the supplied camera each frame
  mesh.userData.update = () => {
    if (ctx.camera) {
      mesh.lookAt(ctx.camera.position);
    }
  };

  // Attach empty handler map for external wiring
  mesh.userData.handlers = {};

  // Cleanup routine
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    // Texture may be shared; do not forcibly dispose.
    // Cancel any GSAP timelines that might have been started elsewhere.
    gsap.globalTimeline.clear();
  };

  // Apply any cinematic primitives declared in the config
  for (const primitive of cinematicPrimitives) {
    const fn = ctx.primitives[primitive.name];
    if (typeof fn === 'function') {
      fn(mesh, primitive.params);
    }
  }

  return mesh;
}
